/**
 * The hazards that used to need interleaving hooks, expressed on the applier: the store's applier thread is paused and
 * stepped one unit at a time, commits land between units, and every exact view is checked against LMDB on the same
 * pinned snapshot.
 */
@Timeout(120)
class LmdbAdjacencyApplierCutoverTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P1 = VF.createIRI("urn:p1");
	private static final IRI P2 = VF.createIRI("urn:p2");
	private static final IRI G = VF.createIRI("urn:g");

	@TempDir
	File dataDir;

	private SailRepository repository;
	private LmdbStore sail;
	private LmdbDirectAdjacencyStore store;
	private TripleStore tripleStore;

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private void open(DirectAdjacencyCoverage coverage, List<IRI> selected) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30)
				.setInitialRunImportEnabled(false)
				.setDirectAdjacencyCoverage(coverage);
		if (selected != null) {
			config.setDirectAdjacencyPredicates(selected);
		}
		sail = new LmdbStore(dataDir, config);
		repository = new SailRepository(sail);
		repository.init();
		store = sail.getBackingStore().directAdjacencyStore();
		tripleStore = sail.getBackingStore().getTripleStore();
	}

	private static IRI s(int i) {
		return VF.createIRI("urn:s" + i);
	}

	private static IRI o(int i) {
		return VF.createIRI("urn:o" + i);
	}

	private void commit(IRI predicate, int from, int count) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin(IsolationLevels.READ_COMMITTED);
			for (int i = from; i < from + count; i++) {
				conn.add(s(i), predicate, o(i), G);
			}
			conn.commit();
		}
	}

	private long id(IRI iri) throws IOException {
		return sail.getBackingStore().valueStore().getId(iri);
	}

	private void seedAndServe() {
		commit(P1, 0, 4);
		assertThat(store.buildNowForTest()).isTrue();
		assertThat(store.applierStateForTest().status()).isEqualTo(Status.SERVING);
	}

	/** Pauses the applier so later commits only reach the log, then runs one build unit and waits for the worker. */
	private void pauseAndSubmitRebuild() {
		store.pauseApplierForTest(true);
		store.requestRebuild();
		stepUntilBuildSubmitted();
		assertThat(store.awaitWorkersIdleForTest(60, TimeUnit.SECONDS)).as("the build worker finished").isTrue();
	}

	/** Steps the paused applier through its queued units until the build worker has been submitted. */
	private void stepUntilBuildSubmitted() {
		stepUntil(store::buildInFlightForTest, "the build was submitted to a worker");
	}

	/**
	 * Steps the paused applier one unit at a time until the condition holds. Units other than the one a test is
	 * interested in (a state release, a seal wake-up) may be queued ahead of it; stepping past them keeps the test
	 * about the effect, not about inbox order.
	 */
	private void stepUntil(java.util.function.BooleanSupplier condition, String description) {
		for (int steps = 0; steps < 20 && !condition.getAsBoolean(); steps++) {
			assertThat(store.stepApplierForTest()).as("applier unit %d before: %s", steps, description).isTrue();
		}
		assertThat(condition.getAsBoolean()).as(description).isTrue();
	}

	private void resumeAndSettle() {
		store.pauseApplierForTest(false);
		assertThat(store.awaitServingForTest(60, TimeUnit.SECONDS)).as("applier serves the head").isTrue();
		AdjacencyState<LmdbInMemoryAdjacencyIndex, LmdbAdjacencyOverlaySet> state = store.applierStateForTest();
		assertThat(state.status()).isEqualTo(Status.SERVING);
		assertThat(state.appliedRevision()).isEqualTo(tripleStore.getDataRevision());
		assertThat(state.gapFromRevision()).isEqualTo(Long.MAX_VALUE);
	}

	@Test
	void aCommitBetweenTheScanAndTheCandidateIsReplayedOntoTheNewBase() throws Exception {
		open(DirectAdjacencyCoverage.FULL, null);
		seedAndServe();
		pauseAndSubmitRebuild();
		long pinned = tripleStore.getDataRevision();
		commit(P1, 10, 3); // lands after the scan, before the candidate is consumed
		assertThat(tripleStore.getDataRevision()).isEqualTo(pinned + 1);
		stepUntil(() -> !store.buildInFlightForTest(), "the candidate unit publishes the new base");
		AdjacencyState<LmdbInMemoryAdjacencyIndex, LmdbAdjacencyOverlaySet> published = store.applierStateForTest();
		assertThat(published.status()).isEqualTo(Status.SERVING);
		assertThat(published.base().baseRevision()).isEqualTo(pinned);
		assertThat(published.appliedRevision()).isEqualTo(pinned);
		assertExactAtHeadAfter(P1, 10, 3);
	}

	@Test
	void aSelectedPredicateFirstCommittedBeforeThePinKeepsItsRows() throws Exception {
		open(DirectAdjacencyCoverage.SELECTED, List.of(P1, P2));
		seedAndServe();
		store.pauseApplierForTest(true);
		commit(P2, 20, 3); // the first rows of a configured predicate, before the build pins
		store.requestRebuild();
		stepUntilBuildSubmitted();
		assertThat(store.awaitWorkersIdleForTest(60, TimeUnit.SECONDS)).isTrue();
		stepUntil(() -> !store.buildInFlightForTest(), "the candidate unit");
		assertExactAtHeadAfter(P2, 20, 3);
	}

	@Test
	void aSelectedPredicateFirstCommittedAfterThePinIsClassifiedByTheApplier() throws Exception {
		open(DirectAdjacencyCoverage.SELECTED, List.of(P1, P2));
		seedAndServe();
		pauseAndSubmitRebuild();
		commit(P2, 30, 3); // the first rows of a configured predicate, after the pin
		stepUntil(() -> !store.buildInFlightForTest(), "the candidate unit");
		assertExactAtHeadAfter(P2, 30, 3);
	}

	@Test
	void aGapReportedDuringARebuildRetiresOnceTheRebuildPinsBeyondIt() throws Exception {
		open(DirectAdjacencyCoverage.FULL, null);
		seedAndServe();
		pauseAndSubmitRebuild();
		commit(P1, 40, 2);
		long gap = tripleStore.getDataRevision();
		store.reportCorruption(gap, "injected");
		stepUntil(() -> tripleStore.adjacencyCommitLog().record(gap).kind() == AdjacencyCommitLog.Kind.OVERFLOWED,
				"the corruption unit marks the revision as a gap");
		try (LmdbAdjacencyReadView view = store.acquire(gap)) {
			assertThat(view.isExact()).isFalse();
			assertThat(view.fallbackReason()).isEqualTo(FallbackReason.REVISION_GAP);
		}
		resumeAndSettle();
		assertThat(store.applierStateForTest().base().baseRevision()).isGreaterThanOrEqualTo(gap);
		assertExactAtHead(P1, 40, 2);
	}

	@Test
	void readersAtTheHeadGetRowLevelPendingViewsUntilTheApplierCatchesUp() throws Exception {
		open(DirectAdjacencyCoverage.FULL, null);
		seedAndServe();
		store.pauseApplierForTest(true);
		commit(P1, 50, 2);
		long head = tripleStore.getDataRevision();
		AdjacencyCommitLog.Record record = tripleStore.adjacencyCommitLog().record(head);
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (!record.sealed() && System.nanoTime() < deadline) {
			Thread.onSpinWait();
		}
		assertThat(record.sealed()).isTrue();
		try (LmdbAdjacencyReadView view = store.acquire(head)) {
			assertThat(view.isExact()).as("a sealed pending record serves with row-level pending").isTrue();
			assertThat(view.state().pending()).hasSize(1);
			assertThat(view.state().appliedRevision()).isEqualTo(head - 1);
			assertServedRowsMatchLmdb(view, head, P1, 0, 4); // untouched rows still serve
		}
		resumeAndSettle();
		try (LmdbAdjacencyReadView view = store.acquire(head)) {
			assertThat(view.isExact()).isTrue();
			assertThat(view.state().pending()).isEmpty();
			assertServedRowsMatchLmdb(view, head, P1, 50, 2);
		}
	}

	@Test
	void writeAdmissionIsReleasedWhenMaintenanceIsDeferred() throws Exception {
		open(DirectAdjacencyCoverage.FULL, null);
		seedAndServe();
		store.pauseApplierForTest(true);
		assertThat(store.tryBeginBackingWrite()).isTrue();
		store.endBackingWrite();
		store.deferMaintenanceForInitialImport();
		stepUntil(() -> store.applierStateForTest().status() == Status.UNAVAILABLE, "the suspend unit");
		assertThat(store.tryBeginBackingWrite()).as("a deferred applier never blocks writers").isTrue();
		store.endBackingWrite();
		store.resumeMaintenanceAfterInitialImport();
		resumeAndSettle();
	}

	// ------------------------------------------------------------------
	// oracle
	// ------------------------------------------------------------------

	/**
	 * A delta apply, a range-merge candidate for an older prefix and a fold request are pending at once. Whichever the
	 * applier consumes first, the others are validated against the new prefix and either spliced in or discarded, and
	 * every exact view along the way reads what LMDB holds.
	 */
	@Test
	void pendingDeltaMergeCandidateAndFoldAreEachValidatedAgainstThePrefix() throws Exception {
		open(DirectAdjacencyCoverage.FULL, null);
		seedAndServe();
		store.pauseApplierForTest(true);
		// four single-row commits: a full normal-band fan-out, which the policy merges once they are applied
		for (int i = 0; i < 4; i++) {
			commit(P1, 10 + i, 1);
		}
		long fourApplied = tripleStore.getDataRevision();
		settleUntil(() -> store.applierStateForTest().appliedRevision() == fourApplied, "four deltas applied");
		settleUntil(store::compactionInFlightForTest, "the policy submitted a range merge");
		assertThat(store.awaitWorkersIdleForTest(60, TimeUnit.SECONDS)).as("the merge worker finished").isTrue();
		// now a fifth delta and a fold request wait beside the merge candidate
		commit(P2, 20, 1);
		long head = tripleStore.getDataRevision();
		store.requestFoldForTest();

		for (int steps = 0; steps < 40; steps++) {
			if (!store.stepApplierForTest()) {
				assertThat(store.awaitWorkersIdleForTest(60, TimeUnit.SECONDS)).isTrue();
			}
			AdjacencyState<LmdbInMemoryAdjacencyIndex, LmdbAdjacencyOverlaySet> state = store.applierStateForTest();
			assertThat(state.status()).as("step %d: %s", steps, state).isEqualTo(Status.SERVING);
			assertThat(state.gapFromRevision()).isEqualTo(Long.MAX_VALUE);
			assertRowsServedAtApplied(state, P1, 0, 4);
			assertRowsServedAtApplied(state, P1, 10, 4);
			if (state.appliedRevision() == head && !store.compactionInFlightForTest()
					&& store.awaitApplierIdleForTest(1, TimeUnit.MILLISECONDS)) {
				break;
			}
		}
		resumeAndSettle();
		store.awaitCompactionForTest();
		AdjacencyState<LmdbInMemoryAdjacencyIndex, LmdbAdjacencyOverlaySet> settled = store.applierStateForTest();
		assertThat(settled.overlays() == null ? 0 : settled.overlays().generationCount())
				.as("the fold absorbed the merged prefix; at most the delta that landed beside it remains: %s",
						store.publicationDiagnostics())
				.isLessThanOrEqualTo(1);
		assertThat(store.snapshotMetrics().deltaMerges).isPositive();
		assertThat(store.snapshotMetrics().baseFolds).isPositive();
		assertExactAtHead(P1, 0, 4);
		assertExactAtHead(P1, 10, 4);
		assertExactAtHead(P2, 20, 1);
	}

	/** Steps the paused applier, waiting for workers between units, until the condition holds. */
	private void settleUntil(java.util.function.BooleanSupplier condition, String description) {
		for (int steps = 0; steps < 60 && !condition.getAsBoolean(); steps++) {
			if (!store.stepApplierForTest()) {
				assertThat(store.awaitWorkersIdleForTest(60, TimeUnit.SECONDS)).as("workers idle: %s", description)
						.isTrue();
			}
		}
		assertThat(condition.getAsBoolean()).as(description).isTrue();
	}

	/** Every subject's row committed at or below the state's applied revision is served exactly from a view there. */
	private void assertRowsServedAtApplied(AdjacencyState<LmdbInMemoryAdjacencyIndex, LmdbAdjacencyOverlaySet> state,
			IRI predicate, int from, int count) throws Exception {
		long p = id(predicate);
		try (LmdbAdjacencyReadView view = store.acquire(state.appliedRevision())) {
			assertThat(view.isExact()).as("exact at applied %d: %s", state.appliedRevision(), view.fallbackReason())
					.isTrue();
			for (int i = from; i < from + count; i++) {
				assertThat(probe(view, null, id(s(i)), p)).as("subject %d at applied %d", i, state.appliedRevision())
						.hasSize(1);
			}
		}
	}

	private void assertExactAtHeadAfter(IRI predicate, int from, int count) throws Exception {
		resumeAndSettle();
		assertExactAtHead(predicate, from, count);
	}

	private void assertExactAtHead(IRI predicate, int from, int count) throws Exception {
		long head = tripleStore.getDataRevision();
		try (LmdbAdjacencyReadView view = store.acquire(head)) {
			assertThat(view.isExact()).as("exact view at the head %d: %s", head, view.fallbackReason()).isTrue();
			assertThat(view.state().pending()).isEmpty();
			assertServedRowsMatchLmdb(view, head, predicate, from, count);
		}
	}

	/** Every bound-subject probe for the given rows is served and equals LMDB's answer on a pinned snapshot. */
	private void assertServedRowsMatchLmdb(LmdbAdjacencyReadView view, long revision, IRI predicate, int from,
			int count) throws Exception {
		long p = id(predicate);
		try (TxnManager.Txn txn = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			assertThat(txn.snapshotRevision()).isEqualTo(revision);
			for (int i = from; i < from + count; i++) {
				long subject = id(s(i));
				List<long[]> served = probe(view, txn, subject, p);
				List<long[]> expected = lmdbRows(txn, subject, p);
				assertThat(served).as("rows for subject %d predicate %s at revision %d", i, predicate, revision)
						.usingRecursiveComparison()
						.isEqualTo(expected);
				assertThat(expected).isNotEmpty();
			}
		}
	}

	private List<long[]> probe(LmdbAdjacencyReadView view, TxnManager.Txn txn, long subject, long predicate)
			throws IOException {
		RecordIterator iterator = store.tryOpen(view, txn, subject, predicate, 0L, -1L, true);
		assertThat(iterator).as("bound-subject probe must be served from adjacency").isNotNull();
		return drain(iterator);
	}

	private List<long[]> lmdbRows(TxnManager.Txn txn, long subject, long predicate) throws IOException {
		return drain(tripleStore.getTriples(txn, subject, predicate, 0L, -1L, true));
	}

	private static List<long[]> drain(RecordIterator iterator) throws IOException {
		List<long[]> rows = new ArrayList<>();
		try {
			long[] quad;
			while ((quad = iterator.next()) != null) {
				rows.add(new long[] { quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX],
						quad[TripleIndex.OBJ_IDX], Math.max(0, quad[TripleIndex.CONTEXT_IDX]) });
			}
		} finally {
			iterator.close();
		}
		rows.sort(Comparator.<long[]>comparingLong(r -> r[0])
				.thenComparingLong(r -> r[1])
				.thenComparingLong(r -> r[2])
				.thenComparingLong(r -> r[3]));
		return rows;
	}
}
